// EditorHandle turns a click or a key into the screen's event. ok is false when
// the message raises none. f is the frame the screen last returned.
func EditorHandle(f Frame, msg tea.Msg) (EditorEvent, bool) {
	switch m := msg.(type) {
	case tea.MouseClickMsg:
		if r, ok := f.eventAt(m.X, m.Y); ok {
			switch r.Event {
			case "Pick":
				return EditorPick{X: m.X - r.X, Y: m.Y - r.Y}, true
			case "Hint":
				return EditorHint{X: m.X - r.X, Y: m.Y - r.Y}, true
			}
		}
	}
	_ = f
	return nil, false
}
